import{_ as i,o as a,c as e,ao as t}from"./chunks/framework.CGAfXaNK.js";const E=JSON.parse('{"title":"3D forward modelling","description":"","frontmatter":{},"headers":[],"relativePath":"forward/3d.md","filePath":"forward/3d.md","lastUpdated":null}'),n={name:"forward/3d.md"};function h(d,s,l,p,r,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="3D-forward-modelling" tabindex="-1">3D forward modelling <a class="header-anchor" href="#3D-forward-modelling" aria-label="Permalink to &quot;3D forward modelling {#3D-forward-modelling}&quot;">​</a></h1><p>MTGeophysics.jl has no 3D solver of its own. For 3D it uses <a href="https://github.com/magnetotellurics/ModEM" target="_blank" rel="noreferrer">ModEM</a>, a well-tested MPI-parallel solver, and handles everything around it: reading and writing the files, running ModEM, and comparing its predictions with the data. In this section we look at each of these steps.</p><h2 id="Read-and-write-3D-files" tabindex="-1">Read and write 3D files <a class="header-anchor" href="#Read-and-write-3D-files" aria-label="Permalink to &quot;Read and write 3D files {#Read-and-write-3D-files}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_data_modem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># impedance tensor and tipper</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_ws3d_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># WS3D model, log10 ρ in memory</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_ws3d_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;new.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dx, m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dy, m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dz, m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A, m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">origin)</span></span></code></pre></div><p>WS3D is the model format of ModEM 3D. <code>load_ws3d_model</code> marks air cells as <code>NaN</code>, so topography is easy to recognise in memory.</p><h2 id="Run-ModEM" tabindex="-1">Run ModEM <a class="header-anchor" href="#Run-ModEM" aria-label="Permalink to &quot;Run ModEM {#Run-ModEM}&quot;">​</a></h2><p>A ModEM forward run takes a model and a data file and writes the predicted data:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mpirun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 21</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Mod3DMT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.rho</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pred.dat</span></span></code></pre></div><p><code>-F</code> means forward, and <code>-n</code> sets the number of MPI processes. The <a href="./../inversion/3d_vfsa">3D VFSA inversion</a> runs this command for you at every step.</p><h2 id="Compare-with-the-data" tabindex="-1">Compare with the data <a class="header-anchor" href="#Compare-with-the-data" aria-label="Permalink to &quot;Compare with the data {#Compare-with-the-data}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> chi2_and_rms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pred.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rms</span></span></code></pre></div><p>The RMS is computed from the impedances and, when present, the tipper.</p><p>Some sites suffer from galvanic distortion: small bodies near the surface that scale the electric field. <code>chi2_and_rms_distorted</code> fits a real 2 × 2 distortion matrix to each site before computing the misfit, which shows how much of the misfit is due to distortion:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> chi2_and_rms_distorted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pred.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; damping </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.01</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>damping</code> pulls each matrix towards the identity: 0 lets it fit freely, larger values allow less correction.</p><h2 id="Apparent-resistivity-and-phase" tabindex="-1">Apparent resistivity and phase <a class="header-anchor" href="#Apparent-resistivity-and-phase" aria-label="Permalink to &quot;Apparent resistivity and phase {#Apparent-resistivity-and-phase}&quot;">​</a></h2><p><code>load_data_modem</code> also computes the apparent resistivity and phase of every component, with their errors, as <code>d.ρ</code>, <code>d.φ</code>, <code>d.ρerr</code> and <code>d.φerr</code>. Their size is (periods, components, sites).</p>`,17)])])}const c=i(n,[["render",h]]);export{E as __pageData,c as default};
